 for(const card of document.querySelectorAll('.glyph-card')){card.classList.toggle('active',card.dataset.glyph===selected);card.querySelector('canvas').setAttribute('aria-label',`Editar ${card.dataset.glyph} · ${(state.glyphs[card.dataset.glyph]||[]).length} módulos`)}
