for(const [name,step]of [['previous',-1],['next',1]])$('#'+name).onclick=()=>{const chars=GROUPS[group];selected=chars[(chars.indexOf(selected)+step+chars.length)%chars.length];render();centerGlyph(selected);persist()};
$('#shape').onchange=()=>action(()=>{setGlobalStyle(state,'shape',$('#shape').value)});$('#grid-size').onchange=()=>action(()=>{const [c,r]=$('#grid-size').value.split('x').map(Number);state=resizeGrid(state,c,r)});
