(async()=>{try{if(params.has('project')){document.querySelector('main').inert=true;$('#save-status').textContent='Abriendo proyecto…';const record=await getProject(id);if(!record||record.studio!=='foundry')throw Error('Proyecto no disponible');state=validate(record.state);$('#project-title').value=record.name;createdAt=record.createdAt;baseline=signature();$('#save-status').textContent=projectSavedLabel()}ready=true;document.querySelector('main').inert=false;sync();schedule();}catch(error){$('#feedback').textContent=error.message;document.querySelector('main').inert=true;console.error(error)}})();

