function syncExtras(){const o=state.overrides?.[selected]||{};for(const key of ['shape','weight','advance'])$('#local-'+key).value=o[key]??'';const t=tester();for(const key of ['size','leading','align','bg'])$('#type-'+key).value=t[key];$('#text-preview').style.justifyContent=({left:'flex-start',center:'center',right:'flex-end'})[t.align];$('#text-preview').style.background=t.bg==='dark'?'#242424':'#f4f2f5';$('#detail-title').textContent=selected;}
for(const key of ['shape','weight','advance'])$('#local-'+key).onchange=()=>{const value=$('#local-'+key).value;if(value!==''&&key!=='shape'&&(!Number.isFinite(+value)||+value<(key==='weight'?10:1)||+value>(key==='weight'?140:44))){syncExtras();syncTypography();syncStyles();return;}action(()=>{state.overrides??={};state.overrides[selected]??={};if(value==='')delete state.overrides[selected][key];else state.overrides[selected][key]=key==='shape'?value:+value})};
