function closeDetail(){if(detailCard&&detailMarker){detailMarker.replaceWith(detailCard);}detailCard=detailMarker=null;$('#glyph-detail').close();}
function openDetail(glyph){setPan(false);if(detailCard)closeDetail();selected=glyph;const card=[...board.children].find(c=>c.dataset.glyph===glyph);if(!card)return;detailMarker=document.createComment('glyph');card.before(detailMarker);detailCard=card;$('#detail-host').append(card);render();$('#glyph-detail').showModal();}
