document.addEventListener('pointerdown',event=>{if(!typeMenu.contains(event.target))typeMenu.open=false});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&typeMenu.open){typeMenu.open=false;typeMenu.querySelector('summary').focus()}});

function syncTypography(){const m=metrics(state);for(const key of Object.keys(m)){const input=$('#metric-'+key);if(input)input.value=+m[key].toFixed(3)}$('#metric-baseline').max=state.rows;$('#local-width').value=state.overrides?.[selected]?.width??'';$('#local-rule').value=state.overrides?.[selected]?.rule??'';$('#global-rule').value=state.rule||'none';const list=$('#component-list'),value=list.value;list.replaceChildren(...Object.keys(state.components||{}).map(name=>{const o=document.createElement('option');o.value=o.textContent=name;return o}));if([...list.options].some(o=>o.value===value))list.value=value;$('#component-status').textContent=(state.links?.[selected]||[]).map(l=>l.name+' ('+l.x+', '+l.y+')').join(' · ')||'Sin vínculos';const pairs=$('#kern-list');pairs.replaceChildren(...Object.entries(state.kerning||{}).slice(0,24).map(([pair,value])=>{const b=document.createElement('button');b.textContent=pair+' '+value;b.onclick=()=>{$('#kern-pair').value=pair;$('#kern-value').value=value};return b}));}
for(const key of ['baseline','ascent','descent','capHeight','xHeight'])$('#metric-'+key).onchange=()=>{const value=+$('#metric-'+key).value,next={...state,metrics:{...metrics(state),[key]:value}};try{validateTypography(next);action(()=>{state.metrics=next.metrics});$('#metric-status').textContent=''}catch(e){$('#metric-status').textContent=e.message;syncTypography()}};
for(const key of ['width','rule'])$('#local-'+key).onchange=()=>{const value=$('#local-'+key).value;const next=clone(state);next.overrides??={};next.overrides[selected]??={};if(value==='')delete next.overrides[selected][key];else next.overrides[selected][key]=key==='width'?+value:value;try{validateTypography(next);action(()=>{state=next})}catch(e){$('#feedback').textContent=e.message;syncTypography()}};
$('#global-rule').onchange=()=>{const value=$('#global-rule').value;action(()=>{state.rule=value})};
$('#kern-pair').oninput=()=>{$('#kern-value').value=state.kerning?.[$('#kern-pair').value]||0};
$('#kern-save').onclick=()=>{const pair=$('#kern-pair').value,value=+$('#kern-value').value;if([...pair].length!==2||!Number.isFinite(value)||value< -10||value>10){$('#feedback').textContent='Ingresá dos caracteres y un ajuste entre −10 y 10.';return;}action(()=>{state.kerning??={};state.kerning[pair]=value;state.previewText=pair+' '+pair+' '+pair});};
$('#kern-delete').onclick=()=>action(()=>{if(state.kerning)delete state.kerning[$('#kern-pair').value]});
$('#generate-accents').onclick=()=>{let count=0;action(()=>{count=generateAccents(state)});$('#generator-status').textContent=count+' acentos generados. Las letras existentes se conservaron.'};
$('#generate-widths').onclick=()=>action(()=>{state.overrides??={};for(const c of Object.keys(state.glyphs)){const cells=cellsFor(state,c);if(!cells.length)continue;state.overrides[c]??={};state.overrides[c].advance=Math.min(40,(Math.max(...cells.map(i=>i%state.columns))+1)*(state.overrides[c].width??100)/100+1)}$('#generator-status').textContent='Avances ajustados al extremo derecho + 1 celda.'});
$('#component-save').onclick=()=>{const name=$('#component-name').value.trim();if(!/^[a-zA-Z0-9 _-]{1,40}$/.test(name)||['__proto__','constructor','prototype'].includes(name)){ $('#feedback').textContent='Usá un nombre de hasta 40 letras, números, espacios o guiones.';return;}const cells=state.glyphs[selected]||[];if(!cells.length){$('#feedback').textContent='Dibujá módulos propios para guardar el componente.';return;}action(()=>{state.components??={};state.components[name]={points:cells.map(i=>[i%state.columns,Math.floor(i/state.columns)])}});$('#component-list').value=name;};
$('#component-attach').onclick=()=>{const name=$('#component-list').value,x=+$('#component-x').value,y=+$('#component-y').value;if(!name||![x,y].every(v=>Number.isInteger(v)&&Math.abs(v)<=20))return;if((state.links?.[selected]?.length||0)>=20)return;action(()=>{state.links??={};state.links[selected]??=[];state.links[selected].push({name,x,y})})};
$('#component-bake').onclick=()=>action(()=>{state.glyphs[selected]=cellsFor(state,selected);if(state.links)delete state.links[selected]});
$('#component-remove').onclick=()=>action(()=>{if(state.links)delete state.links[selected]});
function showAudit(){const report=audit(state),box=$('#audit-results');box.replaceChildren();for(const text of [report.characters+' caracteres dibujados',...report.errors.map(s=>'Error: '+s),...report.warnings.map(s=>'Revisar: '+s)]){const p=document.createElement('p');p.textContent=text;box.append(p)}return report;}
$('#font-audit').onclick=showAudit;
for(const button of document.querySelectorAll('[data-font]'))button.onclick=async()=>{finishEdit();const report=showAudit();if(report.errors.length){$('#feedback').textContent=report.errors.join(' ');return;}const snapshot=clone(state),name=title(),downloadName=filename(),type=button.dataset.font,buttons=[...document.querySelectorAll('[data-font]')];buttons.forEach(b=>b.disabled=true);$('#feedback').textContent='Construyendo '+type.toUpperCase()+'…';try{const {bytes}=await buildFont(snapshot,name,type);const url=URL.createObjectURL(new Blob([bytes],{type:'font/'+type})),link=document.createElement('a');link.href=url;link.download=downloadName+'.'+type;link.click();setTimeout(()=>URL.revokeObjectURL(url),60000);closeMenu();$('#feedback').textContent=type.toUpperCase()+' validado y descargado'+(report.warnings.length?' · revisá las observaciones':'');}catch(e){$('#feedback').textContent=e.message;console.error(e)}finally{buttons.forEach(b=>b.disabled=false)}};

$('#auto-fit').onclick=()=>{try{let result;action(()=>{const next=clone(state);result=autoFit(next);next.autoFitSignature=JSON.stringify([next.glyphs,next.shape,next.weight,next.rule,next.components,next.links]);state=next});$('#auto-fit-status').textContent=result.characters+' letras ajustadas · '+result.pairs+' pares equilibrados. Probá una frase en Live Type.';}catch(error){$('#auto-fit-status').textContent=error.message}};
$('#simple-accents').onclick=()=>{let count=0;action(()=>{count=generateAccents(state)});$('#auto-fit-status').textContent=count?count+' acentos creados. Podés retocarlos en el board.':'No hay acentos pendientes con una letra base disponible.'};
document.querySelector('.advanced-settings').addEventListener('toggle',render);

function styleNames(){return {dots:'Puntos',rounded:'Continuo',squares:'Cuadrados',ring:'Anillos',ribbon:'Cinta',capsule:'Cápsula',bevel:'Biselado',organic:'Orgánico',diamond:'Rombos',triangle:'Triángulos'}}
function syncStyles(){const names=styleNames();$('#style-current').textContent=names[state.shape]||state.shape;const roundness=state.roundness??(state.shape==='squares'?0:55);$('#roundness').value=roundness;$('#roundness-value').textContent=roundness+' %';$('#separation').value=state.separation||0;$('#separation-value').textContent=(state.separation||0)+' %';$('#roundness-control').hidden=!['rounded','squares','ribbon','organic'].includes(state.shape);$('#separation-control').hidden=['rounded','ribbon','organic'].includes(state.shape);}
function showStyles(){const grid=$('#style-options');grid.replaceChildren();for(const [shape,name]of Object.entries(styleNames())){const button=document.createElement('button');button.className='style-option';button.setAttribute('aria-pressed',String(shape===state.shape));const demo={...state,columns:5,rows:7,shape,weight:85,roundness:state.roundness,overrides:{},links:{},rule:'none',color:'#e5e5e5',glyphs:{A:[2,6,8,10,14,15,16,17,18,19,20,24,25,29,30,34]}};button.innerHTML=glyphSVG(demo,'A');const label=document.createElement('span');label.textContent=name;button.append(label);button.onclick=()=>{action(()=>{setGlobalStyle(state,'shape',shape)});$('#style-dialog').close()};grid.append(button)}$('#style-dialog').showModal()}
$('#style-open').onclick=showStyles;$('#style-close').onclick=()=>$('#style-dialog').close();

window.addEventListener('basement-library-changed',()=>{if(!ready){location.reload();return;}baseline='';persist();});

registerStudioSession({save:async()=>{if(!ready)throw Error('Artboard is not ready.');finishEdit();while(writing)await new Promise(r=>setTimeout(r,20));await persist();if(signature()!==baseline)throw Error($('#save-status').textContent||'Save failed.');},capture:()=>({id,name:title(),studio:'foundry',state:clone(state),preview:$('#glyph-preview').toDataURL('image/png'),createdAt,updatedAt:Date.now()}),dirty:()=>ready&&signature()!==baseline});
